class Solution {
public:
    struct Item {
        int dist;
        int price;
        int r;
        int c;
    };

    struct Comparator {
        bool operator()(const Item& a, const Item& b) const {
            if (a.dist != b.dist) return a.dist < b.dist;
            if (a.price != b.price) return a.price < b.price;
            if (a.r != b.r) return a.r < b.r;
            return a.c < b.c;
        }
    };

    vector<vector<int>> highestRankedKItems(vector<vector<int>>& grid, vector<int>& pricing, vector<int>& start, int k) {
        int m = grid.size();
        int n = grid[0].size();
        int low = pricing[0];
        int high = pricing[1];
        int sr = start[0];
        int sc = start[1];

        queue<pair<int, int>> q;
        q.push({sr, sc});
        int start_price = grid[sr][sc];
        grid[sr][sc] = 0;

        priority_queue<Item, vector<Item>, Comparator> pq;

        if (start_price >= low && start_price <= high) {
            pq.push(Item{0, start_price, sr, sc});
            if (pq.size() > k) {
                pq.pop();
            }
        }

        int dist = 0;
        int dr[] = {0, 0, 1, -1};
        int dc[] = {1, -1, 0, 0};

        while (!q.empty()) {
            int size = q.size();
            dist++;
            for (int i = 0; i < size; ++i) {
                pair<int, int> p = q.front();
                q.pop();
                int r = p.first;
                int c = p.second;

                for (int j = 0; j < 4; ++j) {
                    int nr = r + dr[j];
                    int nc = c + dc[j];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] != 0) {
                        int price = grid[nr][nc];
                        grid[nr][nc] = 0;
                        q.push({nr, nc});

                        if (price >= low && price <= high) {
                            pq.push(Item{dist, price, nr, nc});
                            if (pq.size() > k) {
                                pq.pop();
                            }
                        }
                    }
                }
            }
        }

        vector<vector<int>> res;
        while (!pq.empty()) {
            Item item = pq.top();
            pq.pop();
            res.push_back({item.r, item.c});
        }
        reverse(res.begin(), res.end());
        return res;
    }
};
